Index: apps/studio/src/features/flags.test.ts
===================================================================
--- apps/studio/src/features/flags.test.ts	
+++ apps/studio/src/features/flags.test.ts	
@@ -0,0 +1,89 @@
+import { describe, expect, it, beforeEach } from "vitest";
+
+import {
+  FEATURE_FLAGS,
+  clearFeatureOverride,
+  isFeatureEnabled,
+  parseFlagValue,
+  resolveFlag,
+  setFeatureOverride,
+} from "./flags";
+
+describe("parseFlagValue", () => {
+  it.each([
+    ["1", true],
+    ["true", true],
+    ["ON", true],
+    [" yes ", true],
+    ["0", false],
+    ["false", false],
+    ["Off", false],
+    ["nope", null],
+    ["", null],
+    [null, null],
+    [undefined, null],
+  ])("parses %j as %j", (raw, expected) => {
+    expect(parseFlagValue(raw as string | null | undefined)).toBe(expected);
+  });
+});
+
+describe("first-run wizard flag", () => {
+  beforeEach(() => {
+    window.localStorage.clear();
+  });
+
+  it("is on by default", () => {
+    expect(resolveFlag("firstRunWizard", {}).source).toBe("default");
+    expect(isFeatureEnabled("firstRunWizard", {})).toBe(true);
+  });
+
+  it("reads a build-time env override", () => {
+    expect(resolveFlag("firstRunWizard", { env: "off" })).toEqual({
+      enabled: false,
+      source: "env",
+      raw: "off",
+    });
+  });
+
+  it("lets a stored override beat the env", () => {
+    expect(resolveFlag("firstRunWizard", { env: "off", stored: "on" })).toEqual({
+      enabled: true,
+      source: "storage",
+      raw: "on",
+    });
+  });
+
+  it("lets a query override beat storage", () => {
+    expect(resolveFlag("firstRunWizard", { env: "off", stored: "off", query: "on" })).toEqual({
+      enabled: true,
+      source: "query",
+      raw: "on",
+    });
+  });
+
+  it("falls through when a higher-precedence value is unrecognized", () => {
+    const resolved = resolveFlag("firstRunWizard", {
+      query: "maybe",
+      stored: "off",
+      env: "on",
+    });
+    expect(resolved.enabled).toBe(false);
+    expect(resolved.source).toBe("storage");
+  });
+
+  it("writes and clears a local override", () => {
+    setFeatureOverride("firstRunWizard", false);
+    expect(window.localStorage.getItem("studio.flags.firstRunWizard")).toBe("off");
+    expect(resolveFlag("firstRunWizard", { stored: window.localStorage.getItem("studio.flags.firstRunWizard") }).enabled).toBe(false);
+
+    clearFeatureOverride("firstRunWizard");
+    expect(window.localStorage.getItem("studio.flags.firstRunWizard")).toBeNull();
+  });
+
+  it("declares an env variable for every flag", () => {
+    for (const definition of Object.values(FEATURE_FLAGS)) {
+      expect(definition.envVar).toMatch(/^VITE_/);
+      expect(definition.description.length).toBeGreaterThan(0);
+    }
+  });
+});

Index: apps/studio/src/onboarding/OnboardingProvider.tsx
===================================================================
--- apps/studio/src/onboarding/OnboardingProvider.tsx	
+++ apps/studio/src/onboarding/OnboardingProvider.tsx	
@@ -0,0 +1,86 @@
+import { useCallback, useEffect, useMemo, useState, type ReactNode } from "react";
+
+import { isFeatureEnabled } from "../features/flags";
+import { OnboardingContext, type OnboardingController } from "./context";
+import type { GoalId } from "./content";
+import {
+  advanceTour,
+  createOnboardingState,
+  finishTour,
+  retreatTour,
+  selectGoal,
+  shouldAutoOpen,
+  skipTour,
+  startTour,
+  type OnboardingState,
+} from "./machine";
+import { readOnboardingState, writeOnboardingState } from "./storage";
+
+export interface OnboardingProviderProps {
+  children: ReactNode;
+  /** Override for tests and stories; defaults to the `firstRunWizard` flag. */
+  enabled?: boolean;
+}
+
+export function OnboardingProvider({ children, enabled }: OnboardingProviderProps) {
+  const featureEnabled = enabled ?? isFeatureEnabled("firstRunWizard");
+
+  const [state, setState] = useState<OnboardingState>(
+    () => readOnboardingState() ?? createOnboardingState(),
+  );
+  const [open, setOpen] = useState<boolean>(() => featureEnabled && shouldAutoOpen(state));
+
+  // Persist every transition so closing the app mid-tour resumes where it left off.
+  useEffect(() => {
+    if (featureEnabled) {
+      writeOnboardingState(state);
+    }
+  }, [featureEnabled, state]);
+
+  const chooseGoal = useCallback((goal: GoalId) => {
+    setState((prev) => selectGoal(prev, goal));
+  }, []);
+
+  const advance = useCallback(() => {
+    setState(advanceTour);
+  }, []);
+
+  const back = useCallback(() => {
+    setState(retreatTour);
+  }, []);
+
+  const complete = useCallback(() => {
+    setState(finishTour);
+    setOpen(false);
+  }, []);
+
+  const skip = useCallback(() => {
+    setState(skipTour);
+    setOpen(false);
+  }, []);
+
+  const restart = useCallback(() => {
+    if (!featureEnabled) {
+      return;
+    }
+    setState(startTour);
+    setOpen(true);
+  }, [featureEnabled]);
+
+  const value = useMemo<OnboardingController>(
+    () => ({
+      enabled: featureEnabled,
+      open,
+      state,
+      chooseGoal,
+      advance,
+      back,
+      complete,
+      skip,
+      restart,
+    }),
+    [featureEnabled, open, state, chooseGoal, advance, back, complete, skip, restart],
+  );
+
+  return <OnboardingContext.Provider value={value}>{children}</OnboardingContext.Provider>;
+}

Index: apps/studio/src/onboarding/context.ts
===================================================================
--- apps/studio/src/onboarding/context.ts	
+++ apps/studio/src/onboarding/context.ts	
@@ -0,0 +1,30 @@
+import { createContext, useContext } from "react";
+
+import type { GoalId } from "./content";
+import type { OnboardingState } from "./machine";
+
+/**
+ * The wizard's public surface. Components outside the onboarding module only
+ * ever need `enabled` (to show a replay entry) and `restart`.
+ */
+export interface OnboardingController {
+  enabled: boolean;
+  open: boolean;
+  state: OnboardingState;
+  chooseGoal: (goal: GoalId) => void;
+  advance: () => void;
+  back: () => void;
+  complete: () => void;
+  skip: () => void;
+  restart: () => void;
+}
+
+export const OnboardingContext = createContext<OnboardingController | null>(null);
+
+export function useOnboarding(): OnboardingController {
+  const value = useContext(OnboardingContext);
+  if (!value) {
+    throw new Error("useOnboarding must be used within an OnboardingProvider");
+  }
+  return value;
+}

Index: apps/studio/src/onboarding/machine.ts
===================================================================
--- apps/studio/src/onboarding/machine.ts	
+++ apps/studio/src/onboarding/machine.ts	
@@ -0,0 +1,85 @@
+import { GOAL_STEP_INDEX, STEPS, type GoalId, type WizardStepId } from "./content";
+
+/**
+ * Pure flow rules for the first-run tour. No React, no storage, no DOM — the
+ * whole sequence can be reasoned about and tested as plain functions.
+ */
+
+export const ONBOARDING_VERSION = 1;
+export const LAST_STEP_INDEX = STEPS.length - 1;
+
+export type OnboardingStatus = "pending" | "active" | "done" | "skipped";
+
+export interface OnboardingState {
+  status: OnboardingStatus;
+  step: number;
+  goal: GoalId | null;
+  version: number;
+}
+
+export function createOnboardingState(
+  overrides: Partial<OnboardingState> = {},
+): OnboardingState {
+  return {
+    status: "pending",
+    step: 0,
+    goal: null,
+    version: ONBOARDING_VERSION,
+    ...overrides,
+  };
+}
+
+export function clampStep(step: number): number {
+  if (!Number.isFinite(step)) {
+    return 0;
+  }
+  return Math.min(LAST_STEP_INDEX, Math.max(0, Math.trunc(step)));
+}
+
+export function stepAt(step: number): WizardStepId {
+  return STEPS[clampStep(step)].id;
+}
+
+/** A tour the user has neither finished nor skipped should greet them. */
+export function shouldAutoOpen(state: OnboardingState): boolean {
+  return state.status === "pending" || state.status === "active";
+}
+
+export function isFinished(state: OnboardingState): boolean {
+  return state.status === "done" || state.status === "skipped";
+}
+
+/** Replay: start from the top, forget the previous choice. */
+export function startTour(state: OnboardingState): OnboardingState {
+  return { ...state, status: "active", step: 0, goal: null };
+}
+
+export function advanceTour(state: OnboardingState): OnboardingState {
+  if (isFinished(state)) {
+    return state;
+  }
+  // The flow will not leave the starting-point step without a choice.
+  if (state.step === GOAL_STEP_INDEX && state.goal === null) {
+    return state;
+  }
+  return { ...state, status: "active", step: clampStep(state.step + 1) };
+}
+
+export function retreatTour(state: OnboardingState): OnboardingState {
+  if (isFinished(state)) {
+    return state;
+  }
+  return { ...state, status: "active", step: clampStep(state.step - 1) };
+}
+
+export function selectGoal(state: OnboardingState, goal: GoalId): OnboardingState {
+  return { ...state, goal };
+}
+
+export function finishTour(state: OnboardingState): OnboardingState {
+  return { ...state, status: "done", step: LAST_STEP_INDEX };
+}
+
+export function skipTour(state: OnboardingState): OnboardingState {
+  return { ...state, status: "skipped" };
+}

